import json,os,stat,http.client,subprocess
from pathlib import Path
p=Path('/etc/nginx/sites-available/pink-iptv-https.conf')
ren=Path('/etc/letsencrypt/renewal/pink-iptv.duckdns.org.conf')
old=Path('/var/lib/pink-iptv-acme030')
new=Path('/srv/projects/pink-iptv/www/acme')
out={'audit':'PINK_ACME_failure_baseline','read_only':True,'nginx_conf_lines':[], 'sites_enabled':[], 'paths':{},'probe':{},'running':{}}
if p.is_file():out['nginx_conf_lines']=[str(i+1)+': '+l.strip()[:200] for i,l in enumerate(p.read_text(errors='replace').splitlines())]
enabled=Path('/etc/nginx/sites-enabled')
if enabled.is_dir():out['sites_enabled']=[x.name for x in enabled.iterdir() if 'pink' in x.name.lower()]
for path in (old,old/'.well-known',old/'.well-known/acme-challenge',new,new.parent,Path('/srv/projects/pink-iptv')):
 x={'exists':path.exists(),'is_dir':path.is_dir(),'is_link':path.is_symlink()}
 if path.exists():
  s=path.stat();x.update({'mode':oct(stat.S_IMODE(s.st_mode)),'uid':s.st_uid})
  x['readable_by_nginx_user']=subprocess.run(['runuser','-u','www-data','--','/usr/bin/test','-r',str(path)],capture_output=True,timeout=8).returncode==0
 out['paths'][str(path)]=x
if ren.is_file():
 data=ren.read_text(errors='replace')
 out['renewal']={'uses_old_root':data.count(str(old)),'uses_new_root':data.count(str(new))}
def probe(host):
 c=http.client.HTTPConnection('127.0.0.1',80,timeout=6)
 try:
  c.request('GET','/.well-known/acme-challenge/nonexistent-hygiene-check',headers={'Host':host})
  r=c.getresponse();res={'code':r.status,'location':(r.getheader('Location') or '')[:180]};r.read(256);return res
 except Exception as e:return {'error':type(e).__name__}
 finally:c.close()
for h in ('pink-iptv.duckdns.org','localhost'):out['probe'][h]=probe(h)
for n in ('nginx','pink-iptv-backend','pink-vpn'):out['running'][n]=subprocess.run(['systemctl','is-active',n],capture_output=True,text=True,timeout=8).stdout.strip()
print(json.dumps(out,separators=(',',':')))
